1	import React, { useEffect, useMemo, useRef, useState } from 'react';
2	import { VisuallyHidden, chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmButton } from '../../atoms/zimmButton';
5	import { ZimmMediaTile } from '../../atoms/zimmMediaTile';
6	import type { ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
7	import { getDesktopLayoutCounts } from './getDesktopLayoutCounts';
8	
9	const messages = defineMessages({
10	  openGallery: { id: 'product_gallery.trigger.open', defaultMessage: 'Open image gallery' },
11	  openGalleryAt: {
12	    id: 'product_gallery.trigger.open_at',
13	    defaultMessage: 'Open image gallery, image {index} of {total}',
14	  },
15	  galleryButton: { id: 'product_gallery.trigger.label', defaultMessage: 'Gallery +{count}' },
16	  // No confirmed Figma frame for this state yet (SFCC-731 AC 1/2/4's plain button, counts of
17	  // 3/4/6) — reasoned default pending sign-off, same as the layout counts in
18	  // getDesktopLayoutCounts.ts.
19	  galleryButtonPlain: { id: 'product_gallery.trigger.label_plain', defaultMessage: 'Gallery' },
20	  goToSlide: { id: 'product_gallery.dot.label', defaultMessage: 'Go to image {index} of {total}' },
21	  currentSlide: { id: 'product_gallery.live.current', defaultMessage: '{alt}. Image {index} of {total}.' },
22	});
23	
24	const ZIMM_PRODUCT_GALLERY_RECIPE = 'ZimmProductGallery';
25	
26	// Item-count layout (which items stack vs grid, grid row width) lives in
27	// getDesktopLayoutCounts.ts, per SFCC-731's Acceptance Criteria. Only the grid's own column
28	// count is needed here, for chunking gridItems into rows.
29	const DESKTOP_GRID_COLUMNS = 2;
30	
31	// SFCC-731 AC 19 — DIS responsive widths per tile type. `base: '100vw'` everywhere below `lg`
32	// (every tile is full-bleed there); the `lg` ceiling is each tile type's own Figma reference
33	// width (zimmMediaTile.css.ts's own comment: stacked 902px, grid 450px) — a fluid column can
34	// render slightly under this on an ultra-wide viewport, which is a fine trade-off against
35	// shipping full raw resolution unconditionally.
36	const STACKED_ITEM_WIDTHS = { base: '100vw', lg: 902 };
37	const GRID_ITEM_WIDTHS = { base: '100vw', lg: 450 };
38	const COMPACT_ITEM_WIDTHS = { base: '100vw' };
39	
40	// ZimmMediaTile (ui-kits/atoms) owns the canonical media-item shape now — re-exported here so
41	// existing importers of this module (product-view/mapImageGroupsToGalleryMedia.ts, this
42	// component's own stories/tests) don't need to change their import path.
43	export type { ZimmGalleryPhotoItem, ZimmGalleryVideoItem, ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
44	
45	type ZimmProductGalleryProps = {
46	  /** Ordered photo/video sequence. Video renders as a positional slot only — see ZimmGalleryVideoItem. */
47	  media: ZimmGalleryMediaItem[];
48	  /**
49	   * Fires when the shopper wants to view the full gallery — clicking anywhere on the gallery,
50	   * or the "Gallery +N" button. The overlay itself is a separate component (SFCC-187 "PDP –
51	   * Image Gallery Open State"), out of scope here — this only surfaces the intent to open it.
52	   */
53	  onOpenGallery?: () => void;
54	  /**
55	   * Defers loading of the first item too, not just the rest. Pass true for set/bundle child
56	   * contexts where the gallery isn't the primary viewport content — mirrors the base
57	   * ImageGallery's `lazy` prop this component replaces on the PDP.
58	   */
59	  lazy?: boolean;
60	  /** Hides the "Gallery"/"Gallery +N" trigger button entirely, regardless of media count. */
61	  showGalleryButton?: boolean;
62	  /**
63	   * SFCC-731 AC 19 — DIS quality (`q` param, 0-100) for every tile's responsive image request.
64	   * Forwarded to `ZimmMediaTile`/`buildDisImageSrc`. Defaults to that function's own default
65	   * (80) when omitted.
66	   */
67	  imageQuality?: number;
68	};
69	
70	const chunk = <TItem,>(items: TItem[], size: number): TItem[][] => {
71	  const rows: TItem[][] = [];
72	  for (let i = 0; i < items.length; i += size) rows.push(items.slice(i, i + size));
73	  return rows;
74	};
75	
76	/**
77	 * Organism — the PDP product image/video gallery (SFCC-731). Desktop (≥1280px) renders a
78	 * stacked editorial column with a trailing 2x2 supporting-shot grid; tablet and mobile share a
79	 * single-image swipeable carousel with dot navigation. Both breakpoints support
80	 * click-anywhere-to-open-the-full-gallery, confirmed against the Figma design walkthrough.
81	 *
82	 * Reusable beyond the PDP — takes a plain `media` sequence rather than the raw SFCC
83	 * `imageGroups` shape, so a caller maps its own product data at the call site (see
84	 * `product-view/index.tsx` for the PDP's mapping from `product.imageGroups`).
85	 */
86	export const ZimmProductGallery = ({
87	  media,
88	  onOpenGallery,
89	  lazy = false,
90	  showGalleryButton = true,
91	  imageQuality,
92	}: ZimmProductGalleryProps) => {
93	  const intl = useIntl();
94	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_GALLERY_RECIPE, {});
95	
96	  const [selectedIndex, setSelectedIndex] = useState(0);
97	  const trackRef = useRef<HTMLDivElement>(null);
98	  const slideRefs = useRef<Array<HTMLDivElement | null>>([]);
99	
100	  // Clamped for every read below (render-time, so there's no frame where a stale index reads
101	  // past the end) — a variation swap can replace `media` with a shorter array without
102	  // `selectedIndex` (state, from before the swap) ever being told to catch up. Without this, an
103	  // out-of-bounds index makes every slide `i !== safeSelectedIndex` true, i.e. every slide goes
104	  // inert at once, and the live region announces a position that doesn't exist (CodeRabbit, PR #81).
105	  const safeSelectedIndex = Math.min(selectedIndex, Math.max(0, media.length - 1));
106	  // Corrects the underlying state too, so later interactions (dot nav, scrollToSlide) aren't
107	  // still working off a stale value once media stabilises.
108	  useEffect(() => {
109	    setSelectedIndex((prev) => Math.min(prev, Math.max(0, media.length - 1)));
110	  }, [media.length]);
111	
112	  // Tracks which slide is most visible in the compact carousel as the shopper swipes — native
113	  // browser scroll-snap handles the gesture itself (see zimmProductGallery.css.ts's
114	  // compactTrack), this just keeps the dots and the last-slide-only button in sync with it.
115	  useEffect(() => {
116	    const track = trackRef.current;
117	    if (!track) return;
118	
119	    const observer = new IntersectionObserver(
120	      (entries) => {
121	        const mostVisible = entries
122	          .filter((e) => e.isIntersecting)
123	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
124	        if (!mostVisible) return;
125	        const index = slideRefs.current.indexOf(mostVisible.target as HTMLDivElement);
126	        if (index >= 0) setSelectedIndex(index);
127	      },
128	      { root: track, threshold: 0.5 },
129	    );
130	
131	    slideRefs.current.forEach((slide) => slide && observer.observe(slide));
132	    return () => observer.disconnect();
133	  }, [media.length]);
134	
135	  // All slides stay mounted for native scroll-snap, so without this a screen reader's swipe/
136	  // read-order encounters every offscreen slide's alt text and controls, not just the current
137	  // one. `inert` removes the rest from both the accessibility tree and keyboard/pointer reach —
138	  // one attribute instead of separately managing aria-hidden and each control's tabIndex.
139	  useEffect(() => {
140	    slideRefs.current.forEach((slide, i) => {
141	      if (slide) slide.inert = i !== safeSelectedIndex;
142	    });
143	  }, [safeSelectedIndex, media.length]);
144	
145	  const scrollToSlide = (index: number) => {
146	    slideRefs.current[index]?.scrollIntoView({ behavior: 'smooth', inline: 'start', block: 'nearest' });
147	  };
148	
149	  // Each dot stays its own independent Tab stop (not roving tabindex) — arrow keys are an
150	  // addition alongside Tab, not a replacement for it. Moves focus only; Enter/Space still
151	  // activates, same as any other button — this doesn't drive scrollToSlide itself.
152	  const dotBarRef = useRef<HTMLDivElement>(null);
153	  const handleDotBarKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
154	    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
155	    const dots = Array.from(dotBarRef.current?.querySelectorAll('button') ?? []);
156	    const currentIndex = dots.indexOf(document.activeElement as HTMLButtonElement);
157	    if (currentIndex === -1) return;
158	    event.preventDefault();
159	    const delta = event.key === 'ArrowRight' ? 1 : -1;
160	    dots[(currentIndex + delta + dots.length) % dots.length]?.focus();
161	  };
162	
163	  const { stackedCount, gridCount, remainingCount, showButton } = useMemo(
164	    () => getDesktopLayoutCounts(media.length),
165	    [media.length],
166	  );
167	  const stackedItems = useMemo(() => media.slice(0, stackedCount), [media, stackedCount]);
168	  const gridItems = useMemo(
169	    () => media.slice(stackedCount, stackedCount + gridCount),
170	    [media, stackedCount, gridCount],
171	  );
172	  const gridRows = useMemo(() => chunk(gridItems, DESKTOP_GRID_COLUMNS), [gridItems]);
173	  const showDesktopButton = showGalleryButton && showButton;
174	
175	  // Plain "Gallery" once nothing's held back (getDesktopLayoutCounts' 3/4/6-item cases),
176	  // "Gallery +N" otherwise. The compact carousel only ever shows one item at a time, so its
177	  // count is always the full total, not a "remaining" count — matches the reviewed Figma frame's
178	  // "+6" label on a 6-image product.
179	  const desktopGalleryButtonLabel =
180	    remainingCount > 0
181	      ? intl.formatMessage(messages.galleryButton, { count: remainingCount })
182	      : intl.formatMessage(messages.galleryButtonPlain);
183	  // SFCC-731 AC 9 — a single image has nothing to count, so the button reads plain "Gallery"
184	  // rather than "Gallery +1".
185	  const compactGalleryButtonLabel =
186	    media.length > 1
187	      ? intl.formatMessage(messages.galleryButton, { count: media.length })
188	      : intl.formatMessage(messages.galleryButtonPlain);
189	  const currentItem = media[safeSelectedIndex];
190	  const currentAlt = currentItem?.kind === 'photo' ? currentItem.alt : currentItem?.posterAlt;
191	
192	  if (media.length === 0) return null;
193	
194	  return (
195	    <chakra.div __css={styles.root} data-testid="zimm-product-gallery">
196	      {/* Desktop: stacked items + trailing 2x2 grid. Each tile gets its own scoped trigger,
197	          in visual/DOM order (stacked first, then the grid row by row), so Tab order matches
198	          the images' visual order and each has its own position-labelled accessible name —
199	          a single grid-spanning trigger gave every tile the same unlabelled "open gallery"
200	          name and put the Gallery+N button ahead of it in tab order. */}
201	      <chakra.div __css={styles.desktopColumn}>
202	        {stackedItems.map((item, i) => {
203	          const isLastStackedCell = gridRows.length === 0 && i === stackedItems.length - 1;
204	          return (
205	            <chakra.div key={i} __css={styles.desktopItem}>
206	              <ZimmMediaTile item={item} eager={i === 0 && !lazy} widths={STACKED_ITEM_WIDTHS} quality={imageQuality} />
207	              <chakra.button
208	                type="button"
209	                __css={styles.triggerOverlay}
210	                aria-label={intl.formatMessage(messages.openGalleryAt, { index: i + 1, total: media.length })}
211	                onClick={onOpenGallery}
212	              />
213	              {isLastStackedCell && showDesktopButton && (
214	                <chakra.div __css={styles.desktopButtonWrapper}>
215	                  <ZimmButton
216	                    label={desktopGalleryButtonLabel}
217	                    variant="primary"
218	                    inverse
219	                    onClick={onOpenGallery}
220	                    sx={styles.galleryButton}
221	                  />
222	                </chakra.div>
223	              )}
224	            </chakra.div>
225	          );
226	        })}
227	        {gridRows.length > 0 && (
228	          <chakra.div __css={styles.desktopGrid}>
229	            {gridRows.map((row, rowIdx) => (
230	              <chakra.div key={rowIdx} __css={styles.desktopGridRow}>
231	                {row.map((item, colIdx) => {
232	                  const isLastCell = rowIdx === gridRows.length - 1 && colIdx === row.length - 1;
233	                  const index = stackedCount + rowIdx * DESKTOP_GRID_COLUMNS + colIdx;
234	                  return (
235	                    <chakra.div key={colIdx} __css={{ ...styles.desktopItem, flex: 1 }}>
236	                      <ZimmMediaTile item={item} eager={false} widths={GRID_ITEM_WIDTHS} quality={imageQuality} />
237	                      <chakra.button
238	                        type="button"
239	                        __css={styles.triggerOverlay}
240	                        aria-label={intl.formatMessage(messages.openGalleryAt, {
241	                          index: index + 1,
242	                          total: media.length,
243	                        })}
244	                        onClick={onOpenGallery}
245	                      />
246	                      {isLastCell && showDesktopButton && (
247	                        <chakra.div __css={styles.desktopButtonWrapper}>
248	                          <ZimmButton
249	                            label={desktopGalleryButtonLabel}
250	                            variant="primary"
251	                            inverse
252	                            onClick={onOpenGallery}
253	                            sx={styles.galleryButton}
254	                          />
255	                        </chakra.div>
256	                      )}
257	                    </chakra.div>
258	                  );
259	                })}
260	              </chakra.div>
261	            ))}
262	          </chakra.div>
263	        )}
264	      </chakra.div>
265	
266	      {/* Tablet + mobile: single-image swipeable carousel. */}
267	      <chakra.div __css={styles.compactColumn}>
268	        <chakra.div __css={styles.compactTrack} ref={trackRef}>
269	          {media.map((item, i) => (
270	            <chakra.div
271	              key={i}
272	              __css={styles.compactSlide}
273	              data-testid={`zimm-product-gallery-slide-${i}`}
274	              ref={(el: HTMLDivElement | null) => {
275	                slideRefs.current[i] = el;
276	              }}
277	            >
278	              {/* Never eager here, even for i === 0 — desktopColumn/compactColumn are both
279	                  always mounted (CSS display:none toggles which is visible), so marking both
280	                  trees' first tile eager fetched the same hero image twice on every load
281	                  (CodeRabbit, PR #81). The desktop stacked tile above keeps eager priority. */}
282	              <ZimmMediaTile item={item} eager={false} widths={COMPACT_ITEM_WIDTHS} quality={imageQuality} />
283	            </chakra.div>
284	          ))}
285	        </chakra.div>
286	        <chakra.button
287	          type="button"
288	          __css={styles.triggerOverlay}
289	          aria-label={intl.formatMessage(messages.openGallery)}
290	          onClick={onOpenGallery}
291	        />
292	        {media.length > 1 && (
293	          <chakra.div __css={styles.dotBar} ref={dotBarRef} onKeyDown={handleDotBarKeyDown}>
294	            {media.map((_, i) => (
295	              <ZimmButton
296	                key={i}
297	                variant="icon"
298	                icon={i === safeSelectedIndex ? 'carousel-selected' : 'carousel'}
299	                label={intl.formatMessage(messages.goToSlide, { index: i + 1, total: media.length })}
300	                onClick={() => scrollToSlide(i)}
301	                sx={styles.galleryDot}
302	              />
303	            ))}
304	          </chakra.div>
305	        )}
306	        {/* AC 11 — visible and tappable regardless of which slide is current, not just the last
307	            one (design team correction, 2026-09-05; superseded an earlier last-slide-only read
308	            of a Figma dev annotation). AC 9 — shown for a single image too (plain "Gallery",
309	            see compactGalleryButtonLabel above), unlike the dot bar above which stays hidden —
310	            media.length is always >= 1 here (the component returns null earlier otherwise). */}
311	        {showGalleryButton && (
312	          <chakra.div __css={styles.compactButtonWrapper}>
313	            <ZimmButton
314	              label={compactGalleryButtonLabel}
315	              variant="primary"
316	              inverse
317	              onClick={onOpenGallery}
318	              sx={styles.galleryButton}
319	            />
320	          </chakra.div>
321	        )}
322	        <VisuallyHidden aria-live="polite">
323	          {intl.formatMessage(messages.currentSlide, {
324	            alt: currentAlt ?? '',
325	            index: safeSelectedIndex + 1,
326	            total: media.length,
327	          })}
328	        </VisuallyHidden>
329	      </chakra.div>
330	    </chakra.div>
331	  );
332	};
333	
334	export default ZimmProductGallery;
335

1	import React, { useState } from 'react';
2	import { AspectRatio, Image, chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import DynamicImage from '@salesforce/retail-react-app/app/components/dynamic-image';
5	import { ZimmButton } from '../zimmButton';
6	import { GALLERY_ITEM_ASPECT_RATIO } from './zimmMediaTile.css';
7	import { buildDisImageSrc } from 'app/utils/buildDisImageSrc';
8	
9	/** Same shape base SFCC's `DynamicImage`/`getResponsivePictureAttributes` accept. */
10	export type ZimmMediaTileWidths = (number | string)[] | Record<string, number | string>;
11	
12	const messages = defineMessages({
13	  play: { id: 'product_gallery.video.play', defaultMessage: 'Play video' },
14	  pause: { id: 'product_gallery.video.pause', defaultMessage: 'Pause video' },
15	  mute: { id: 'product_gallery.video.mute', defaultMessage: 'Mute video' },
16	  unmute: { id: 'product_gallery.video.unmute', defaultMessage: 'Unmute video' },
17	});
18	
19	const ZIMM_MEDIA_TILE_RECIPE = 'ZimmMediaTile';
20	
21	export type ZimmGalleryPhotoItem = {
22	  kind: 'photo';
23	  src: string;
24	  alt: string;
25	};
26	
27	export type ZimmGalleryVideoItem = {
28	  kind: 'video';
29	  /**
30	   * Poster frame shown in place of real playback. No product video data source exists yet —
31	   * SFCC-188 ("PDP – Product Video in Gallery") is blocked on a content-modelling workshop for
32	   * how video is stored on the product and ordered in the gallery. This renders the positional
33	   * slot and a real, keyboard-operable control shell (play/pause, mute) ready for SFCC-188 to
34	   * wire an actual source into, but the controls only toggle local UI state today.
35	   */
36	  posterSrc: string;
37	  posterAlt: string;
38	};
39	
40	export type ZimmGalleryMediaItem = ZimmGalleryPhotoItem | ZimmGalleryVideoItem;
41	
42	export type ZimmMediaTileProps = {
43	  item: ZimmGalleryMediaItem;
44	  /** Skips `loading="lazy"` — pass for the item that should load with LCP priority. */
45	  eager?: boolean;
46	  /**
47	   * SFCC-731 AC 19 — this tile's own real rendered width per breakpoint (px/vw, or a single
48	   * value), e.g. `{base: '100vw', lg: 902}`. The atom has no layout context of its own — it's
49	   * reused inside full-bleed stacked items, 2/4-up grid cells, and a fluid mobile carousel, each
50	   * a different real width — so each caller supplies its own. When omitted, the image renders
51	   * at its raw source resolution with no responsive `srcset` (this atom's previous behaviour).
52	   */
53	  widths?: ZimmMediaTileWidths;
54	  /** DIS `q` param (0-100), forwarded to `buildDisImageSrc`. Only used when `widths` is given. */
55	  quality?: number;
56	};
57	
58	/**
59	 * Atom — a single photo or video gallery tile's own visual content: aspect-ratio box, the image
60	 * itself (with a load-failure fallback), and — for a video item — its play/pause/mute control
61	 * shell. No interactive "open gallery" trigger behaviour lives here; that's the caller's
62	 * concern (see ZimmProductGallery's sibling `triggerOverlay` button and ZimmGalleryOverlay's
63	 * plain scrollable stack).
64	 *
65	 * Reused across the PDP's default gallery state (ZimmProductGallery) and its expanded/overlay
66	 * state (ZimmGalleryOverlay, SFCC-731 AC 12-25) so the load-failure and aspect-ratio handling
67	 * can't drift between the two.
68	 */
69	export const ZimmMediaTile = ({ item, eager = false, widths, quality }: ZimmMediaTileProps) => {
70	  const intl = useIntl();
71	  const styles = useMultiStyleConfig(ZIMM_MEDIA_TILE_RECIPE, {});
72	  // No real playback source yet (see ZimmGalleryVideoItem) — these toggle local UI state only,
73	  // ready for SFCC-188 to wire a real <video>/Vimeo source behind.
74	  const [playing, setPlaying] = useState(false);
75	  const [muted, setMuted] = useState(true);
76	  // SFCC-731 AC 21 — a failed load keeps the aspect-ratio box (no layout shift) with a neutral
77	  // fill instead of the browser's broken-image icon. Tracks the SOURCE that failed, not a plain
78	  // boolean — a tile is reused at the same list position across renders (index-keyed), so a
79	  // plain boolean would keep showing the fallback for a brand-new, valid source after a
80	  // variation swap replaces a previously-failed one (CodeRabbit, PR #81).
81	  const [erroredSrc, setErroredSrc] = useState<string | null>(null);
82	  const src = item.kind === 'photo' ? item.src : item.posterSrc;
83	  const alt = item.kind === 'photo' ? item.alt : item.posterAlt;
84	  const hasError = erroredSrc === src;
85	
86	  // SFCC-731 AC 19 — responsive DIS srcset when the caller knows its own real rendered width
87	  // (`widths`); otherwise the raw source, unchanged from this atom's previous behaviour. Shared
88	  // between the photo and video-poster branches below so they can't drift from each other.
89	  const image = hasError ? (
90	    <chakra.div __css={styles.mediaFallback} role="img" aria-label={alt} aria-hidden={alt === '' || undefined} />
91	  ) : widths ? (
92	    <DynamicImage
93	      as={Image}
94	      src={buildDisImageSrc(src, quality)}
95	      widths={widths}
96	      imageProps={{
97	        alt,
98	        loading: eager ? 'eager' : 'lazy',
99	        width: '100%',
100	        height: '100%',
101	        objectFit: 'cover',
102	        onError: () => setErroredSrc(src),
103	      }}
104	      // AspectRatio's own CSS (`& > *:not(style)`) sizes DynamicImage's outer Box correctly,
105	      // since that Box is AspectRatio's direct child — but `<picture>` (DynamicImage's own
106	      // markup, one level further in, not exposed as a prop) is `display: inline` by default
107	      // and gets no sizing from anywhere, so the actual image was rendering near its intrinsic
108	      // pixel size instead of filling the tile. `imageProps`'s width/height only reaches the
109	      // innermost <img>, which then has nothing correctly-sized to resolve "100%" against.
110	      __css={{ '& picture': { display: 'block', width: '100%', height: '100%' } }}
111	    />
112	  ) : (
113	    <Image
114	      src={src}
115	      alt={alt}
116	      loading={eager ? 'eager' : 'lazy'}
117	      objectFit="cover"
118	      onError={() => setErroredSrc(src)}
119	    />
120	  );
121	
122	  if (item.kind === 'photo') {
123	    return <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO}>{image}</AspectRatio>;
124	  }
125	
126	  return (
127	    <>
128	      <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO}>{image}</AspectRatio>
129	      <chakra.div __css={styles.videoControlsWrapper}>
130	        <ZimmButton
131	          variant="icon"
132	          icon={playing ? 'pause' : 'play'}
133	          label={intl.formatMessage(playing ? messages.pause : messages.play)}
134	          onClick={() => setPlaying((p) => !p)}
135	        />
136	        <ZimmButton
137	          variant="icon"
138	          icon="mute"
139	          label={intl.formatMessage(muted ? messages.unmute : messages.mute)}
140	          onClick={() => setMuted((m) => !m)}
141	        />
142	      </chakra.div>
143	    </>
144	  );
145	};
146	
147	export default ZimmMediaTile;
148

1	import React, { useEffect, useRef, useState } from 'react';
2	import {
3	  Image,
4	  Modal,
5	  ModalContent,
6	  ModalOverlay,
7	  VisuallyHidden,
8	  chakra,
9	  useMultiStyleConfig,
10	} from '@chakra-ui/react';
11	import { defineMessages, useIntl } from 'react-intl';
12	import { ZimmButton } from '../../atoms/zimmButton';
13	import { ZimmMediaTile } from '../../atoms/zimmMediaTile';
14	import type { ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
15	import { ZimmColourSwatchGroup } from '../../molecules/zimmColourSwatchGroup';
16	import type { ZimmColourSwatchValue } from '../../molecules/zimmColourSwatchGroup';
17	import { useZimmModal } from 'app/hooks/useZimmModal';
18	import { useUiCopy } from 'app/hooks/useUiCopy';
19	import { buildDisImageSrc, resolveDisImageSrc } from 'app/utils/buildDisImageSrc';
20	
21	const messages = defineMessages({
22	  close: { id: 'gallery_overlay.trigger.close', defaultMessage: 'Close gallery' },
23	  goToImage: { id: 'gallery_overlay.thumbnail.label', defaultMessage: 'Go to image {index} of {total}' },
24	  currentImage: { id: 'gallery_overlay.live.current', defaultMessage: '{alt}. Image {index} of {total}.' },
25	  imageStack: { id: 'gallery_overlay.body.label', defaultMessage: 'Product images' },
26	});
27	
28	const ZIMM_GALLERY_OVERLAY_RECIPE = 'ZimmGalleryOverlay';
29	
30	type ZimmGalleryOverlayProps = {
31	  /** Whether the overlay is open. Nothing renders until this and mount-gating (SSR safety) both
32	   *  clear — see useZimmModal. */
33	  isOpen: boolean;
34	  onClose: () => void;
35	  productName: string;
36	  /** Ordered photo/video sequence — the same shape/order ZimmProductGallery renders. */
37	  media: ZimmGalleryMediaItem[];
38	  /**
39	   * Offered colour values for "Also available in" — the same combined natural + related
40	   * (SFCC-708) set the main PDP sidebar shows. Undefined/single-item hides the row.
41	   */
42	  colourValues?: ZimmColourSwatchValue[];
43	  /** The currently selected colour's `value`, e.g. `colourAttr.selectedValue.value`. */
44	  selectedColourValue?: string;
45	  /**
46	   * SFCC-731 AC 19 — DIS quality (`q` param, 0-100) for every image's responsive request.
47	   * Forwarded to `ZimmMediaTile`/`buildDisImageSrc`. Defaults to that function's own default
48	   * (80) when omitted.
49	   */
50	  imageQuality?: number;
51	};
52	
53	// SFCC-731 AC 19 — matches `bodyInner`'s own BODY_MAX_WIDTH exactly (720px), the real column
54	// width these images render at from `lg` up; full-bleed below that.
55	const IMAGE_WIDTHS = { base: '100vw', lg: 720 };
56	
57	// Thumbnail strip — a single fixed size regardless of breakpoint (matches `thumbnail`'s own
58	// 102px width, zimmGalleryOverlay.css.ts), so this needs a resolved request width rather than
59	// the full responsive `<picture>` machinery. 2x for standard retina density.
60	const THUMBNAIL_REQUEST_WIDTH = 204;
61	// Rendered (CSS) size, for the <img> width/height attributes — half of the 2x request width
62	// above, matching `thumbnail`'s own 102px/3:4 aspect ratio (zimmGalleryOverlay.css.ts).
63	const THUMBNAIL_DISPLAY_WIDTH = 102;
64	const THUMBNAIL_DISPLAY_HEIGHT = 136;
65	
66	/**
67	 * Organism — the SFCC-731 "expanded state" full-screen gallery overlay (AC 12-25). Built
68	 * directly on Chakra's Modal/ModalOverlay/ModalContent (not the ZimmModal atom — that atom's
69	 * chrome is a fixed-maxWidth centered card, a different contract than this full-viewport
70	 * takeover) plus the existing useZimmModal() hook for SSR-safe mount gating. Focus trap, initial
71	 * focus, focus restore to the trigger, body-scroll lock (which also satisfies AC 13's "return to
72	 * the same scroll position" — locking/unlocking overflow never moves window.scrollY), and
73	 * Escape/overlay-click-to-close all come from Chakra rather than being hand-rolled, the same
74	 * reasoning ZimmModal itself documents.
75	 *
76	 * Only true desktop (`lg`, 992px, and up — the same breakpoint ZimmProductGallery itself uses)
77	 * renders the 3-column sticky header (name + colour selector | thumbnail jump-strip | close)
78	 * above a centred, max-width image column. Tablet follows the mobile layout instead (design team
79	 * direction, 2026-09-05): name + close on one row, colour selector below, no thumbnail strip,
80	 * full-width image column — matches Figma nodes 40001999:5982 (desktop) and 40001999:5751
81	 * (mobile/tablet), confirmed via the Figma MCP 2026-09-04.
82	 */
83	export const ZimmGalleryOverlay = ({
84	  isOpen,
85	  onClose,
86	  productName,
87	  media,
88	  colourValues,
89	  selectedColourValue,
90	  imageQuality,
91	}: ZimmGalleryOverlayProps) => {
92	  const intl = useIntl();
93	  const { t } = useUiCopy();
94	  const styles = useMultiStyleConfig(ZIMM_GALLERY_OVERLAY_RECIPE, {});
95	  const { mounted } = useZimmModal({ isOpen, onClose });
96	
97	  const [activeIndex, setActiveIndex] = useState(0);
98	  const itemRefs = useRef<Array<HTMLDivElement | null>>([]);
99	  const thumbBarRef = useRef<HTMLDivElement>(null);
100	  // State-backed refs, not plain useRefs — ModalContent (and everything inside it, including
101	  // this body div) mounts through Chakra's own Portal, which does its own two-pass mount (an
102	  // internal effect flips a "has portal target" flag before the real DOM node exists). A plain
103	  // `useRef` + a dependency-array-triggered effect can miss the commit where React actually
104	  // attaches the node — confirmed by instrumenting this exact effect: `mounted` flipped true a
105	  // full render before `bodyRef.current` was non-null. A callback ref (via useState) sidesteps
106	  // this entirely: it fires exactly when React attaches/detaches the real node, whichever commit
107	  // that happens on, and storing it in state makes any effect depending on it re-run then too —
108	  // the same fix ZimmModal already documents for its own `contentNode`.
109	  const [contentNode, setContentNode] = useState<HTMLElement | null>(null);
110	  const [bodyNode, setBodyNode] = useState<HTMLDivElement | null>(null);
111	
112	  const titleId = 'zimm-gallery-overlay-title';
113	
114	  // Clamped for every read below, same reasoning as ZimmProductGallery's own selectedIndex
115	  // clamp (CodeRabbit, PR #81) — a colour swap can shrink `media` without activeIndex (state,
116	  // from before the swap) ever being told to catch up.
117	  const safeActiveIndex = Math.min(activeIndex, Math.max(0, media.length - 1));
118	  useEffect(() => {
119	    setActiveIndex((prev) => Math.min(prev, Math.max(0, media.length - 1)));
120	  }, [media.length]);
121	
122	  /*
123	   * `aria-labelledby` as a plain prop on `<ModalContent>` is silently dropped by
124	   * @chakra-ui/modal (confirmed by ZimmModal's own investigation of chunk-XG6IELTC.mjs's
125	   * getDialogProps — it recomputes both aria ids from its own ModalHeader/ModalBody-mount
126	   * tracking, always undefined for a modal like this one that renders its own markup rather
127	   * than Chakra's ModalHeader/ModalBody slots). Setting the attribute directly on the mounted
128	   * DOM node, via a callback ref so the effect fires exactly when Chakra's own Portal actually
129	   * attaches the node, is the same workaround ZimmModal already uses.
130	   */
131	  useEffect(() => {
132	    if (!isOpen || !contentNode) return;
133	    contentNode.setAttribute('aria-labelledby', titleId);
134	  }, [isOpen, contentNode]);
135	
136	  // Starts scrolled to the top every time the overlay opens — no click-to-index requirement in
137	  // the current AC set (SFCC-731 AC 12-25 doesn't specify which image opens selected). Depends
138	  // on `bodyNode` (state), not `mounted` — see that state's own comment for why a dependency on
139	  // `mounted` alone isn't reliable here.
140	  useEffect(() => {
141	    if (isOpen && bodyNode) bodyNode.scrollTop = 0;
142	  }, [isOpen, bodyNode]);
143	
144	  // Keeps the thumbnail strip and live region in sync as the shopper scrolls the image stack —
145	  // mirrors ZimmProductGallery's own IntersectionObserver sync for its compact carousel.
146	  useEffect(() => {
147	    if (!isOpen || !bodyNode) return;
148	
149	    const observer = new IntersectionObserver(
150	      (entries) => {
151	        const mostVisible = entries
152	          .filter((entry) => entry.isIntersecting)
153	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
154	        if (!mostVisible) return;
155	        const index = itemRefs.current.indexOf(mostVisible.target as HTMLDivElement);
156	        if (index >= 0) setActiveIndex(index);
157	      },
158	      { root: bodyNode, threshold: 0.5 },
159	    );
160	
161	    itemRefs.current.forEach((item) => item && observer.observe(item));
162	    return () => observer.disconnect();
163	  }, [isOpen, bodyNode, media.length]);
164	
165	  const scrollToItem = (index: number) => {
166	    itemRefs.current[index]?.scrollIntoView({ behavior: 'smooth', block: 'start' });
167	  };
168	
169	  // Same roving-focus technique as ZimmProductGallery's dot bar — each thumbnail stays its own
170	  // independent Tab stop (not roving tabindex); ArrowLeft/ArrowRight are an addition alongside
171	  // Tab, moving focus only. Duplicated rather than extracted into a shared hook — a small
172	  // (~10-line) function, and extracting it wasn't part of this task's requested scope.
173	  const handleThumbBarKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
174	    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
175	    const thumbs = Array.from(thumbBarRef.current?.querySelectorAll('button') ?? []);
176	    const currentIndex = thumbs.indexOf(document.activeElement as HTMLButtonElement);
177	    if (currentIndex === -1) return;
178	    event.preventDefault();
179	    const delta = event.key === 'ArrowRight' ? 1 : -1;
180	    thumbs[(currentIndex + delta + thumbs.length) % thumbs.length]?.focus();
181	  };
182	
183	  const currentItem = media[safeActiveIndex];
184	  const currentAlt = currentItem?.kind === 'photo' ? currentItem.alt : currentItem?.posterAlt;
185	
186	  // SFCC-731 AC 20 — no media, nothing to show. Same empty-state guard ZimmProductGallery uses.
187	  if (!mounted || media.length === 0) return null;
188	
189	  const closeButton = (
190	    <ZimmButton
191	      variant="icon"
192	      icon="close"
193	      label={intl.formatMessage(messages.close)}
194	      onClick={onClose}
195	      sx={styles.closeButton}
196	    />
197	  );
198	
199	  const nameText = (
200	    <chakra.p aria-hidden textStyle="productNames" color="var(--zimm-color-text-default)">
201	      {productName}
202	    </chakra.p>
203	  );
204	
205	  // AC 15 — circle swatches, shown at every viewport whenever the product has at least one
206	  // offered colour. Reuses ZimmColourSwatchGroup directly (variant="circle") — the same molecule
207	  // the main PDP sidebar uses, so related-colour (SFCC-708) forceReload navigation, keyboard nav,
208	  // and pagination all come for free instead of being reimplemented here. The group itself
209	  // suppresses the swatch row (but keeps the label) when there's only one offered colour — see
210	  // its own "offered.length === 0" / "offered.length > 1" gates — so the single-colour case
211	  // still shows "Colour: <name>", matching the main PDP exactly, instead of being omitted.
212	  // The multi-colour case uses the gallery-specific "Also available in" wording instead of the
213	  // PDP's field-style "Colour:" — one offered colour is a field ("Colour: Guava Seascape"),
214	  // several are alternatives ("Also available in"), so the two labels intentionally diverge.
215	  const offeredColourCount = (colourValues ?? []).filter((v) => Boolean(v.imageUrl) && v.orderable !== false).length;
216	  const colourSwatchesSection = colourValues && offeredColourCount > 0 && (
217	    <chakra.div __css={styles.colourSwatches}>
218	      <ZimmColourSwatchGroup
219	        values={colourValues}
220	        selectedValue={selectedColourValue}
221	        variant="circle"
222	        {...(offeredColourCount > 1
223	          ? { label: t('pdp.gallery_overlay.colourLabel', 'Also available in'), appendColon: false }
224	          : {})}
225	      />
226	    </chakra.div>
227	  );
228	
229	  const thumbnailStrip = media.length > 1 && (
230	    <chakra.div __css={styles.thumbnailStrip} ref={thumbBarRef} onKeyDown={handleThumbBarKeyDown}>
231	      {media.map((item, i) => {
232	        const thumbSrc = item.kind === 'photo' ? item.src : item.posterSrc;
233	        return (
234	          <chakra.button
235	            key={i}
236	            type="button"
237	            __css={styles.thumbnail}
238	            aria-label={intl.formatMessage(messages.goToImage, { index: i + 1, total: media.length })}
239	            onClick={() => scrollToItem(i)}
240	          >
241	            {/* alt="" — the button above already carries the accessible name, same pattern as
242	                ZimmProductGallery's click-anywhere trigger over a decorative tile image. */}
243	            <Image
244	              src={resolveDisImageSrc(buildDisImageSrc(thumbSrc, imageQuality), THUMBNAIL_REQUEST_WIDTH)}
245	              alt=""
246	              loading="lazy"
247	              htmlWidth={THUMBNAIL_DISPLAY_WIDTH}
248	              htmlHeight={THUMBNAIL_DISPLAY_HEIGHT}
249	              objectFit="cover"
250	              __css={styles.thumbnailImage}
251	            />
252	          </chakra.button>
253	        );
254	      })}
255	    </chakra.div>
256	  );
257	
258	  return (
259	    // size="full" — Chakra's own built-in full-viewport dialog size (clears the default `md`
260	    // max-width and centering margin at the source, via the same theme-resolution path Chakra
261	    // uses internally, rather than trying to out-fight it from outside).
262	    //
263	    // ModalContent below uses `sx`, not `__css`, for the same reason: confirmed by reading
264	    // @chakra-ui/modal's ModalContent source (chunk-6TYU4DP7.mjs) — it spreads
265	    // `{...dialogProps, __css: dialogStyles}`, so an `__css` prop passed in from here lands in
266	    // `dialogProps` but is then unconditionally overwritten by Chakra's own `__css: dialogStyles`
267	    // key later in the same object literal, making it silently inert. `sx` is a different prop
268	    // name entirely, so it doesn't collide with that key and reaches Chakra's higher-priority
269	    // style resolution instead. ModalOverlay's own implementation spreads in the opposite order
270	    // (`__css` first, `...rest` — which includes ours — last), so `__css` does work there; kept
271	    // as-is rather than switched for no reason.
272	    <Modal isOpen={isOpen} onClose={onClose} motionPreset="none" size="full">
273	      <ModalOverlay __css={styles.overlay} />
274	      <ModalContent ref={setContentNode} sx={styles.panel}>
275	        <VisuallyHidden as="h2" id={titleId}>
276	          {productName}
277	        </VisuallyHidden>
278	
279	        {/* Desktop only (`lg` and up): name + colour selector | thumbnail strip | close.
280	            The visible name is `aria-hidden` — the VisuallyHidden h2 above already carries the
281	            dialog's one accessible name; this is purely the visual duplicate CSS toggles per
282	            breakpoint, same pattern ZimmProductGallery already uses for its desktop/compact
283	            columns. */}
284	        <chakra.div __css={styles.desktopHeader}>
285	          <chakra.div __css={styles.desktopHeaderStart}>
286	            {nameText}
287	            {colourSwatchesSection}
288	          </chakra.div>
289	          {thumbnailStrip}
290	          {closeButton}
291	        </chakra.div>
292	
293	        {/* Below `lg` (tablet + mobile): name + close on one row, colour selector below, no
294	            thumbnail strip. */}
295	        <chakra.div __css={styles.mobileHeader}>
296	          <chakra.div __css={styles.mobileHeaderTop}>
297	            {nameText}
298	            {closeButton}
299	          </chakra.div>
300	          {colourSwatchesSection}
301	        </chakra.div>
302	
303	        {/* axe: scrollable-region-focusable — the only interactive content in this region is
304	            the thumbnail strip and close button, both outside it, so the scrollable container
305	            itself needs to be a keyboard-reachable Tab stop for arrow/Page keys to scroll it. */}
306	        <chakra.div
307	          __css={styles.body}
308	          ref={setBodyNode}
309	          tabIndex={0}
310	          role="region"
311	          aria-label={intl.formatMessage(messages.imageStack)}
312	        >
313	          <chakra.div __css={styles.bodyInner}>
314	            {media.map((item, i) => (
315	              <chakra.div
316	                key={i}
317	                __css={styles.item}
318	                data-testid={`zimm-gallery-overlay-item-${i}`}
319	                ref={(el: HTMLDivElement | null) => {
320	                  itemRefs.current[i] = el;
321	                }}
322	              >
323	                <ZimmMediaTile item={item} eager={i === 0} widths={IMAGE_WIDTHS} quality={imageQuality} />
324	              </chakra.div>
325	            ))}
326	          </chakra.div>
327	        </chakra.div>
328	
329	        <VisuallyHidden aria-live="polite">
330	          {intl.formatMessage(messages.currentImage, {
331	            alt: currentAlt ?? '',
332	            index: safeActiveIndex + 1,
333	            total: media.length,
334	          })}
335	        </VisuallyHidden>
336	      </ModalContent>
337	    </Modal>
338	  );
339	};
340	
341	export default ZimmGalleryOverlay;
